Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -13,9 +13,10 @@
 <div class="help" id="help">MOVE: WASD / ARROWS &nbsp; • &nbsp; JUMP: W / UP &nbsp; • &nbsp; SHOOT: SPACE</div><div class="overlay" id="overlay"><div class="panel"><h1 id="title">BASKETBALL<br>STARS</h1><p id="message">First to outscore the CPU in 60 seconds!</p><button id="start">PLAY NOW</button></div></div></div>
 <script>
 const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');let W,H,dpr;function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
 const keys={};addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='KeyR'&&ended)start()});addEventListener('keyup',e=>keys[e.code]=false);
-let p1,p2,ball,time,started=false,ended=false,last=0,muted=false,particles=[];
+let p1={x:0,y:0,vx:0,vy:0,dir:1,score:0},p2={x:0,y:0,vx:0,vy:0,dir:-1,score:0},ball={x:0,y:0,vx:0,vy:0,r:17,held:true,owner:1,rot:0},time=60,started=false,ended=false,last=0,particles=[];
+p1.x=W*.28;p2.x=W*.72;
 function start(){p1={x:W*.28,y:0,vx:0,vy:0,dir:1,score:0};p2={x:W*.72,y:0,vx:0,vy:0,dir:-1,score:0};ball={x:p1.x,y:0,vx:0,vy:0,r:17,held:true,owner:1,rot:0};time=60;started=true;ended=false;document.getElementById('overlay').classList.add('hidden');document.getElementById('p1').textContent='0';document.getElementById('p2').textContent='0';last=performance.now()}
 function ground(){return H*.78}function hoopY(){return H*.43}function rimX(){return W*.83}
 function playerMove(pl,keysOn,dt,ai=false){const g=ground();if(pl.y===0&&((keysOn===1&&keys.KeyW)||(!ai&&keysOn===2&&keys.ArrowUp)||(!ai&&keysOn===1&&keys.Space&&Math.random()>1))){pl.vy=-Math.min(H*.75,620)}if(!ai){let mx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);pl.vx+=(mx*420-pl.vx)*Math.min(1,dt*8)}else{pl.vx+=(Math.max(-180,Math.min(180,(ball.owner===2||ball.owner===0?ball.x:rimX()-30)-pl.x))*2.2-pl.vx)*Math.min(1,dt*5)}pl.vx*=.995;pl.x=Math.max(48,Math.min(W*.92,pl.x+pl.vx*dt));pl.vy+=H*1.55*dt;pl.y+=pl.vy*dt;if(pl.y>0){pl.y-=pl.vy*dt;pl.vy+=H*1.55*dt;pl.y+=pl.vy*dt}if(pl.y>0&&pl.y+pl.vy*dt>=0){pl.y=0;pl.vy=0}else{pl.y+=pl.vy*dt;if(pl.y>0){pl.y=0;pl.vy=0}}}
 // simpler arcade physics with grounded Y coordinate
